(out / 'mockups.css').write_text(css.strip().replace('}', '}\n').rstrip()+'\n',encoding='utf-8',newline='\n')

def icon(name):
    assert (repo/'assets/icons'/f'{name}.svg').exists(), name
    return f'<span class="icon" aria-hidden="true" style="--src:url(../../../assets/icons/{name}.svg)"></span>'
def control(text, name=None, style=''):
    return f'<span class="control {style}">{icon(name) if name else ""}{escape(text)}</span>'
def header(lang, editor=False):
    en=lang=='en'
    brand='<div class="brand"><img src="../../../assets/odibo/icon-64.png" alt="">ODIBO PDF</div>'
    doc='<span class="title-doc">Предложение.pdf <span class="dirty">●</span></span>' if editor else ''
    undo=f'<span class="header-undo">{icon("undo-2")}<span class="disabled">{icon("redo-2")}</span></span>' if editor else ''
    save=control('Сохранить','save','primary') if editor else ''
    return f'<header class="top">{brand}{control("Open" if en else "Открыть", "folder-open") if editor else ""}{doc}<span class="spacer"></span>{undo}<span class="search">{icon("search")}<span class="hint">{"Find commands" if en else "Поиск команд"}</span><span class="key">Ctrl K</span></span>{save}{icon("sun")}<span class="winbuttons">{icon("minus")}{icon("maximize")}{icon("x")}</span></header>'
def sidebar(lang):
    labels=['Home','Recent','All tools','Pinned folders','Settings','Help'] if lang=='en' else ['Главная','Последние','Все инструменты','Папки','Настройки','Помощь']
    names=['house','clock','layout-grid','folder-open','settings','circle-help']
    rows=[f'<div class="navitem {"active" if i==0 else ""}">{icon(n)}{t}</div>' for i,(t,n) in enumerate(zip(labels,names))]
    return '<aside class="sidebar">'+''.join(rows[:4])+'<div class="bottom">'+''.join(rows[4:])+'</div></aside>'
def dashboard(lang):
    en=lang=='en'
    labels=['Open PDF','Edit PDF','Combine','Split','Annotate','Forms','Organize pages','Export'] if en else ['Открыть PDF','Редактировать','Объединить','Разделить','Аннотации','Формы','Организация страниц','Экспорт']
    desc=['Choose a document · Ctrl O','Text and images','Several files into one PDF','Separate pages into files','Highlights and comments','Fill and prepare fields','Rotate, reorder, remove','Choose an available format'] if en else ['Выбрать документ · Ctrl O','Текст и изображения','Несколько файлов в один PDF','Страницы в отдельные файлы','Выделение и комментарии','Заполнение и поля','Порядок, поворот, удаление','Выбрать доступный формат']
    names=['folder-open','file-pen-line','files','scissors','message-square-text','text-cursor-input','layout-grid','file-output']
    actions=''.join(f'<div class="action {"featured" if i==0 else ""}">{icon(n)}<h3>{t}</h3><span class="description">{d}</span></div>' for i,(t,d,n) in enumerate(zip(labels,desc,names)))
    files=[('Project proposal.pdf' if en else 'Предложение.pdf','5','248 KB' if en else '248 КБ'),('Application form.pdf' if en else 'Анкета.pdf','2','132 KB' if en else '132 КБ'),('Meeting notes.pdf' if en else 'Заметки встречи.pdf','3','186 KB' if en else '186 КБ')]
    recent=''.join(f'<div class="recent-row">{icon("file-text")}<div><b>{n}</b><div class="recent-meta">{"Demo documents" if en else "Демонстрационные документы"}</div></div><span class="recent-meta size">{p} {"pages" if en else "стр."} · {size}</span><span class="recent-meta date">{"Today" if en else "Сегодня"}</span>{icon("ellipsis")}</div>' for n,p,size in files)
    return header(lang)+f'<div class="home-shell">{sidebar(lang)}<main class="dashboard"><div class="hero"><div><h1>{"What would you like to do?" if en else "Что нужно сделать с PDF?"}</h1><p>{"Your documents and everyday PDF tools, in one place." if en else "Документы и повседневные инструменты — в одном месте."}</p></div><div class="drop">{icon("file-plus-2")} {"Drop a PDF into this window" if en else "Перетащите PDF в окно"}</div></div><section class="actions">{actions}</section><div class="section-title"><h2>{"Recent documents" if en else "Последние документы"}</h2><span class="link">{"Clear list" if en else "Очистить список"}</span></div><section class="recent">{recent}</section><div class="footnote"><span>{"Local PDF workflows. No account required." if en else "Локальная работа с PDF. Без обязательного аккаунта."}</span><span>{"Sample entries for the mockup" if en else "Пример списка для макета"}</span></div></main></div>'
def thumbnails():
    cards=''.join(f'<div class="thumb {"selected" if i==1 else ""}"><div class="thumb-paper"><b>ODIBO · DEMO</b>'+''.join('<div class="line"></div><div class="line short"></div>' for _ in range(5))+f'</div><span>{i}</span></div>' for i in range(1,4))
    return '<aside class="navigation"><div class="pane-title">Навигация'+icon('panel-left')+'</div><div class="nav-switch"><span class="selected">Страницы</span><span>Закладки</span></div>'+cards+'</aside>'
def editor():
    modes=''.join(f'<span class="mode {"active" if i==1 else ""} {"advanced" if i==5 else ""}">{t}</span>' for i,t in enumerate(['Просмотр','Редактирование','Аннотации','Страницы','Формы','Ещё']))
    toolbar=control('Текст и изображения','text-cursor-input','subtle')+control('Добавить текст','type')+control('Изображение','image-plus','secondary')+control('Ссылка','link-2','secondary')+'<span class="spacer"></span>'+control('Страницы','files','outline compact-only')+control('Свойства','settings-2','outline compact-only')+'<span class="find">'+control('Найти в PDF','search')+'</span>'
    paper='''<article class="paper"><div class="doc-brand">ODIBO / DEMO DOCUMENT</div><h2>Предложение<br>о сотрудничестве</h2><div class="document-meta">Демонстрационный документ · 23 октября 2026</div><p>Этот пример показывает, как документ занимает главное место в рабочей области редактора.</p><div class="selected-text"><span class="handle"></span><p>Редактируйте поддерживаемый текст, добавляйте изображения и сохраняйте изменения в PDF.</p></div><p>Инструменты рядом с выделенным объектом помогают сосредоточиться на текущей задаче.</p><div class="doc-table"><span>Подготовка материалов</span><span>Этап 1</span><span>Проверка и согласование</span><span>Этап 2</span><span>Передача документов</span><span>Этап 3</span></div><div class="document-footer">Синтетический пример для проектного макета. Не реальный PDF.</div></article>'''
    inspector='<aside class="inspector"><div class="pane-title">Свойства текста'+icon('x')+'</div><span class="small muted">Выделен текстовый блок</span><label>Шрифт PDF</label><div class="field">Сохранять исходные'+icon('chevron-down')+'</div><div class="form-row"><div><label>Размер</label><div class="field">14</div></div><div><label>Цвет</label><div class="field"><span class="swatch"></span>'+icon('chevron-down')+'</div></div></div><hr><h3>Добавить в документ</h3>'+''.join(f'<div class="tool-row">{icon(n)}{t}</div>' for t,n in [('Текст','type'),('Изображение','image-plus'),('Ссылку','link-2')])+'<hr><p class="help">Ctrl Z — отменить изменение.<br>Сложная вёрстка PDF может иметь ограничения редактирования.</p></aside>'
    status='<footer class="statusbar"><span class="optional">Изменения не сохранены</span><span class="pager">'+icon('chevron-left')+'1 / 5'+icon('chevron-right')+'</span><span>100 %</span><span>По ширине</span>'+icon('maximize')+'</footer>'
    return header('ru',True)+f'<nav class="modes">{control("Главная", "house")}{modes}<span class="spacer"></span><span class="small muted">Меню</span></nav><div class="toolbar">{toolbar}</div><div class="editor-shell">{thumbnails()}<main class="canvas">{paper}</main>{inspector}</div>{status}'
def combine():
    cards=''.join(f'<div class="file-card">{icon("file-text")}<span class="small muted">{i}</span><h3>{n}</h3><span class="muted small">{p} страницы</span><div class="small link" style="margin-top:18px">Переместить · Убрать из списка</div></div>' for i,n,p in [(1,'Предложение.pdf',5),(2,'Приложение.pdf',2)])
    return header('ru')+'<main class="combine-main"><div class="combine-header">'+icon('chevron-left')+'<div><h1>Объединить PDF</h1><p class="muted">Проверьте порядок файлов перед объединением.</p></div><span class="spacer"></span>'+control('Добавить файлы','file-plus-2','outline')+'</div><div class="combine-list">'+cards+'</div><div class="combine-options"><div><h3>Порядок документов</h3><p class="small muted">Перетаскивание или команды перемещения с клавиатуры.</p></div><span class="small muted">Исходные файлы сохраняются</span></div><div class="combine-summary"><span class="muted">2 файла · 7 страниц</span>'+control('Объединить','files','primary')+'</div><p class="small muted" style="margin-top:25px">Демонстрационный список. Результат открывается в редакторе; сохранение — отдельное действие.</p></main>'

screens=[('dashboard-light-ru','Главная · светлая','light',dashboard('ru'),1440,980),('dashboard-dark-ru','Главная · тёмная','dark',dashboard('ru'),1440,980),('editor-light-ru','Редактор · светлая','light',editor(),1440,980),('editor-dark-ru','Редактор · тёмная','dark',editor(),1440,980),('editor-compact-ru','Редактор · компактный','light',editor(),960,800),('dashboard-light-en','Dashboard · English','light',dashboard('en'),1440,980),('combine-light-ru','Объединение · светлая','light',combine(),1440,980)]
for slug,title,theme,body,w,h in screens:
    doc=f'<!doctype html><html lang="{"en" if slug.endswith("en") else "ru"}"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>ODIBO PDF — {title}</title><link rel="stylesheet" href="../mockups.css"><div class="preview-label"><span>ЭТАП 3.1 · ПРОЕКТНЫЙ МАКЕТ · PDF-действия не подключены</span><span>{title} · {w} × {h}</span></div><section class="window {theme}" aria-label="Проектный макет ODIBO PDF">{body}</section></html>\n'
    (out/'mockups'/f'{slug}.html').write_text(doc.replace('><', '>\n<'),encoding='utf-8',newline='\n')
links=''.join(f'<li><a href="mockups/{s}.html">{t}</a><p>{w} × {h}</p></li>' for s,t,_,_,w,h in screens)
(out/'preview.html').write_text(f'<!doctype html><html lang="ru"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>ODIBO PDF — макеты 3.1</title><link rel="stylesheet" href="mockups.css"><main class="gallery"><h1>ODIBO PDF · проектирование интерфейса</h1><p>Это макеты для согласования структуры, а не работающий PDF-редактор. Команды PDF здесь не запускаются.</p><p>Структура предварительная: упомянутый владельцем визуальный концепт не был доступен в сообщении.</p><ul>{links}</ul><p><a href="UIUX_PLAN.md">План, архитектура и привязка к существующим действиям</a></p><p>Графика ODIBO: LicenseRef-ODIBO-Brand. Иконки Lucide: ISC. Inter: OFL. Новые внешние ассеты не используются.</p></main></html>\n',encoding='utf-8',newline='\n')
